command:
sudo -n mkdir -p /var/www/inventory
sudo -n sh -c 'cat > /var/www/inventory/index.html' <<'ANTRIEB_HTML'
<!doctype html>
<html><head><title>Inventory Application</title></head><body><h1>Inventory Web Application</h1><p>Backend: node2</p><ul><li>Widget A: 42</li><li>Widget B: 17</li></ul></body></html>
ANTRIEB_HTML
sudo -n sh -c 'cat > /etc/nginx/sites-available/inventory' <<'ANTRIEB_NGINX'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;
    root /var/www/inventory;
    index index.html;
    add_header X-Backend node2 always;
    location = /health {
        default_type text/plain;
        return 200 "healthy node2\n";
    }
}
ANTRIEB_NGINX
sudo -n rm -f /etc/nginx/sites-enabled/default
sudo -n ln -sfn /etc/nginx/sites-available/inventory /etc/nginx/sites-enabled/inventory
sudo -n nginx -t
sudo -n systemctl enable nginx
sudo -n systemctl restart nginx
systemctl is-active nginx
curl -fsS -D - "http://$NODE_IP:8080/" -o /tmp/inventory-body
cat /tmp/inventory-body

